    task.wait(0.3)
    for _ = 1, 5 do
        if not RUNNING or not M.alive() then return false, "dead" end
        local p = F.promptOf(e)
        if not p or e.Parent == nil then return false, "gone" end
        pcall(fireproximityprompt, p)
        local t0 = os.clock()
        while os.clock() - t0 < 0.6 and not M.carrying() do task.wait(0.03) end
        if M.carrying() then return true end
        task.wait(0.1)
    end
    return false, "refused"
end
function F.carryMode() return val("f_carry", "TP") == "Glide" and "Glide" or "TP" end
function F.glideHome()
    local s = F.home()
    local r0 = M.root()
    if not s or not r0 then return nil end
    S.carry = nil
    local h0 = M.hum()
    local rate = math.max(20, (S.walk0 and S.walk0 * 0.9 or (h0 and h0.WalkSpeed) or 40) * val("f_glide", 120) / 100)
    S.glideRate = rate
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { lp.Character }
    local desired = r0.CFrame
    local arrived = false
    local function hold()
        local r = M.root()
        if not r then return end
        if (r.Position - desired.Position).Magnitude > 6 then r.CFrame = desired end
        r.AssemblyLinearVelocity = Vector3.zero
        r.AssemblyAngularVelocity = Vector3.zero
    end
    local c1 = RunService.Stepped:Connect(function()
        local c = lp.Character
        for _, p in ipairs(c and c:GetChildren() or {}) do
            if p:IsA("BasePart") then p.CanCollide = false end
        end
        hold()
    end)
    local c2 = RunService.Heartbeat:Connect(function(dt)
        local p = desired.Position
        local flat = Vector3.new(s.X - p.X, 0, s.Z - p.Z)
        local left = flat.Magnitude
        if left < 2 then
            arrived = true
            desired = CFrame.new(s)
        else
            local step = math.min(rate * dt, left)
            local nx = p + flat.Unit * step
            local d = Workspace:Raycast(nx + Vector3.new(0, 10, 0), Vector3.new(0, -40, 0), rp)
            local y = d and d.Position.Y + 3.2 or p.Y
            desired = CFrame.lookAt(Vector3.new(nx.X, y, nx.Z), Vector3.new(s.X, y, s.Z))
        end
        hold()
    end)
    local dist = (Vector3.new(s.X, 0, s.Z) - Vector3.new(r0.Position.X, 0, r0.Position.Z)).Magnitude
    local t0 = os.clock()
    local ok, e = pcall(function()
        while RUNNING and M.alive() and M.carrying() and not S.carry and not arrived and os.clock() - t0 < dist / rate + 6 do task.wait(0.05) end
        local t1 = os.clock()
        while RUNNING and M.alive() and M.carrying() and not S.carry and os.clock() - t1 < 2 do task.wait(0.05) end
    end)
    c1:Disconnect()
    c2:Disconnect()
    if not ok then LOG("glide err", tostring(e)) end
    local c = lp.Character
    for _, n in ipairs({ "Head", "Torso", "UpperTorso", "LowerTorso", "HumanoidRootPart" }) do
        local p = c and c:FindFirstChild(n)
        if p then p.CanCollide = true end
    end
    if not S.carry then task.wait(0.3) end
    return S.carry
end
function F.carryHome()
    if F.carryMode() == "Glide" then return F.glideHome() end
    local s = F.home()
    if not s then return nil end
    S.carry = nil
    for _ = 1, 2 do
        M.go(s)
        local t0 = os.clock()
        while os.clock() - t0 < 2.5 and not S.carry and M.carrying() and M.alive() do task.wait(0.05) end
        if S.carry or not M.carrying() then break end
    end
    if not S.carry then task.wait(0.3) end
    return S.carry
end
function F.takeEgg(e)
    local rar, zone = e:GetAttribute("Rarity"), e:GetAttribute("ZoneIndex")
    local tries = val("f_tries", 6)
    for n = 1, tries do
        if not RUNNING or not M.ready() or not on("f_auto") then return end
        S.task = string.format(__T["Stealing %s (try %d)"], tostring(rar), n)
        if not F.touchLobby() then return end
        if e.Parent == nil or e:GetAttribute("CarriedBy") ~= 0 then return end
        local ok, why = F.grab(e)
        if not ok then
            S.failed += 1
            S.skip[e.Name] = os.clock() + 20
            LOG("steal failed", rar, zone, why)
            return
        end
        S.task = F.carryMode() == "Glide" and string.format(__T["Gliding %s home"], tostring(rar)) or S.task
        local res = F.carryHome()
        if res == "BANK" then
            S.banked += 1
            LOG("banked", rar, zone, "try", n)
            return true
        end
        S.slipped += 1
        LOG("slip", rar, zone, "try", n, tostring(res))
        if M.carrying() then M.fire("RequestDropEgg", {}) task.wait(0.3) end
        task.wait(0.4)
    end
    S.skip[e.Name] = os.clock() + 30
end
function F.area()
    local b = M.base()
    if not b then return nil end
    local raw = b:GetAttribute("PlacementArea")
    if type(raw) ~= "string" then return nil end
    if S.areaRaw == raw and S.areaData then return S.areaData, b end
    local parts = string.split(raw, "|")
    if parts[1] ~= "p1" or #parts ~= 4 then return nil end
    local function parse(s, n)
        local out = {}
        if s == "" then return out end
        for _, row in ipairs(string.split(s, ";")) do
            local v = string.split(row, ",")
            if #v == n then
                local t = {}
                for i = 1, n do t[i] = tonumber(v[i]) or 0 end
                out[#out + 1] = t
            end
        end
        return out
    end
    local a = { rects = parse(parts[2], 4), blocks = parse(parts[3], 6), circles = parse(parts[4], 3) }
    for _, v in ipairs(a.blocks) do v[7], v[8] = math.cos(v[5]), math.sin(v[5]) end
    S.areaRaw, S.areaData = raw, a
    return a, b
end
function F.inRects(a, x, z)
    for _, v in ipairs(a.rects) do
        if v[1] <= x and x <= v[3] and v[2] <= z and z <= v[4] then return true end
    end
    return false
end
function F.valid(a, x, z, used)
    if not F.inRects(a, x, z) then return false end
    for _, o in ipairs({ { 1.5, 0 }, { -1.5, 0 }, { 0, 1.5 }, { 0, -1.5 } }) do
        if not F.inRects(a, x + o[1], z + o[2]) then return false end
    end
    local br = 1.25
    for _, v in ipairs(a.circles) do
        local dx, dz, l = x - v[1], z - v[2], v[3] + br
        if dx * dx + dz * dz < l * l then return false end
    end
    for _, v in ipairs(a.blocks) do
        local dx, dz = x - v[1], z - v[2]
        local p = math.max(math.abs(dx * v[7] - dz * v[8]) - v[3], 0)
        local q = math.max(math.abs(dx * v[8] + dz * v[7]) - v[4], 0)
        if p * p + q * q < br * br then return false end
    end
    for _, u in ipairs(used) do
        local dx, dz, l = x - u.x, z - u.z, math.max(4, 1.75 + u.r) + 0.5
        if dx * dx + dz * dz < l * l then return false end
    end
    return true
end
function F.frame(b)
    local f = b:FindFirstChild("Floor")
    if not f then return nil end
    return f.CFrame * CFrame.new(0, f.Size.Y / 2, 0)
end
function F.used(frame)
    local out = {}
    for _, m in ipairs(M.placed()) do
        local p = frame:PointToObjectSpace(m:GetPivot().Position)
        out[#out + 1] = { x = p.X, z = p.Z, r = tonumber(m:GetAttribute("Radius")) or 1.75 }
    end
    return out
end
function F.freeSpot(a, used, bad)
    for r = 0, 44, 4.5 do
        local n = r == 0 and 1 or math.max(8, math.ceil(2 * math.pi * r / 4.5))
        for i = 0, n - 1 do
            local t = i / n * 2 * math.pi
            local x, z = math.floor((math.cos(t) * r) / 0.25 + 0.5) * 0.25, math.floor((math.sin(t) * r) / 0.25 + 0.5) * 0.25
            local key = x .. "," .. z
            if not bad[key] and F.valid(a, x, z, used) then return x, z, key end
        end
    end
end
function F.eggKey(i)
    if val("e_pick", "Best") == "Fastest" then return -(tonumber(i.growRemaining) or 0) end
    return (F.RANK[i.rarity] or 0) * 1e7 + (i.mutation and i.mutation ~= "" and 1e6 or 0) + (tonumber(i.zone) or 0)
end
function F.placedIds()
    local out = {}
    for _, m in ipairs(M.placed()) do
        local id = m:GetAttribute("ItemId")
        if id then out[id] = true end
    end
    return out
end
function F.unplacedEggs()
    local out = {}
    local live = F.placedIds()
    for _, i in ipairs(M.items()) do
        if i.kind == "Egg" and (not i.placed or i.placed == "") and not live[i.id] and not (S.soldIds and S.soldIds[i.id]) then out[#out + 1] = i end
    end
    table.sort(out, function(a, b) return F.eggKey(a) > F.eggKey(b) end)
    return out
end
function F.freeIncubators()
    return math.max(0, M.num("EggCap") - #M.placed("Egg"))
end
function F.readyEggs()
    local out = {}
    local now, clock = M.now(), os.clock()
    S.hatchAt = S.hatchAt or {}
    for _, m in ipairs(M.placed("Egg")) do
        local st, at, id = m:GetAttribute("State"), tonumber(m:GetAttribute("ReadyAt")) or 0, m:GetAttribute("ItemId")
        if id and (S.hatchAt[id] or 0) < clock and (st == "Ready" or (st == "Growing" and at > 0 and at <= now)) then out[#out + 1] = id end
    end
    return out
end
function F.catboySig()
    local n, inc = 0, 0
    for _, m in ipairs(M.placed("Catboy")) do
        n += 1
        inc += tonumber(m:GetAttribute("Income")) or 0
    end
    return n .. ":" .. inc
end
function F.equipWanted()
    if not S.snap or not D.Plot then return false end
    local pods, worst = 0, nil
    local lv = D.Plot.Pen.Levels[M.num("PenLevel") + 1]
    pods = lv and lv.Pods or 0
    local placed, best = M.placed("Catboy"), 0
    for _, m in ipairs(placed) do
        local r = F.RANK[m:GetAttribute("Rarity")] or 0
        if not worst or r < worst then worst = r end
    end
    for _, i in ipairs(M.items()) do
        if i.kind == "Catboy" and (not i.placed or i.placed == "") then
            local r = F.RANK[i.rarity] or 0
            if r > best then best = r end
        end
    end
    if best == 0 then return false end
    return #placed < pods or (worst ~= nil and best > worst)
end
function F.baseWork()
    if M.carrying() then return false end
    local wantHatch = on("e_hatch") and #F.readyEggs() > 0
    local wantPlace = on("e_place") and S.snap and (S.placeCool or 0) < os.clock() and F.freeIncubators() > 0 and #F.unplacedEggs() > 0
    local wantEquip = on("e_equip") and (S.equipCool or 0) < os.clock() and F.equipWanted()
    if not (wantHatch or wantPlace or wantEquip) then return false end
    if os.clock() - (S.baseAt or 0) < 3 then return false end
    S.baseAt = os.clock()
    local a, b = F.area()
    if not b then return false end
    local frame = F.frame(b)
    if not frame then return false end
    local spot = F.near(frame.Position)
    if not spot then return false end
    S.task = __T["At base"]
    M.go(spot)
    task.wait(0.35)
    if wantHatch then
        for _, id in ipairs(F.readyEggs()) do
            S.hatchAt[id] = os.clock() + 6
            M.fire("RequestHatchEgg", { itemId = id })
            task.wait(0.25)
        end
        task.wait(0.4)
    end
    if wantPlace and a then
        S.badSpots = S.badSpots or {}
        local used, bad, fails = F.used(frame), S.badSpots, 0
        for _, egg in ipairs(F.unplacedEggs()) do
            if F.freeIncubators() <= 0 or not RUNNING then break end
            if fails >= 3 then S.placeCool = os.clock() + 45 break end
            local x, z, key = F.freeSpot(a, used, bad)
            if not x then S.placeCool = os.clock() + 60 break end
            local before = #M.placed("Egg")
            M.fire("RequestPlaceAt", { itemId = egg.id, x = x, z = z, yaw = 0 })
            local t0 = os.clock()
            while os.clock() - t0 < 1.2 and #M.placed("Egg") == before do task.wait(0.05) end
            if #M.placed("Egg") > before then
                S.placed += 1
                used[#used + 1] = { x = x, z = z, r = 1.75 }
            else
                bad[key] = true
                fails += 1
                LOG("place refused", x, z, S.gmsg)
            end
            task.wait(0.2)
        end
    end
    if on("e_equip") and (S.equipCool or 0) < os.clock() and F.equipWanted() then
        local before = F.catboySig()
        M.fire("RequestEquipBest", {})
        local t0 = os.clock()
        while os.clock() - t0 < 1.5 and F.catboySig() == before do task.wait(0.05) end
        S.equipCool = os.clock() + (F.catboySig() == before and 30 or 4)
    end
    return true
end
function F.wheel()
    if M.num("PenLevel") < 1 then return false end
    local b = M.base()
    local t = b and b:FindFirstChild("Treadmill")
    if not t then return false end
    if M.attr("OnTreadmill") == true then return true end
    local s = F.stand(t.Position.X, t.Position.Z, t.Position.Y)
    if not s then return false end
    M.go(s)
    return true
end
task.spawn(function()
    while RUNNING do
        local ok, e = pcall(function()
            if not M.ready() then
                S.task = M.why()
                task.wait(0.4)
                return
            end
            if M.carrying() and on("f_auto") then
                local res = F.carryHome()
                if res == "BANK" then S.banked += 1 elseif res == "SLIP" then S.slipped += 1 end
                if M.carrying() then M.fire("RequestDropEgg", {}) task.wait(0.3) end
            end
            if (S.holdUntil or 0) > os.clock() then
                S.task = __T["Waiting"]
                task.wait(0.3)
                return
            end
            F.baseWork()
            local did = false
            if on("f_auto") then
                if F.bagFull() then
                    S.task = __T["Bag full"]
                else
                    local egg = F.pick()
                    if egg then
                        did = true
                        F.takeEgg(egg)
                    else
                        S.task = __T["No matching eggs"]
                    end
                end
            else
                S.task = __T["Idle"]
            end
            if not did then
                if on("w_auto") and F.wheel() then S.task = __T["On the wheel"] end
                task.wait(0.5)
            end
        end)
        if not ok then
            LOG("main err", tostring(e))
            task.wait(1)
        end
        task.wait(0.05)
    end
end)
local U = {}
function U.keep() return tonumber(val("u_keep", "0")) or 0 end
function U.sellList()
    local out, value = {}, 0
    if not S.snap then return out, value end
    local keepEggs = {}
    if on("e_place") then
        local slots = F.freeIncubators()
        for n, i in ipairs(F.unplacedEggs()) do
            if n > slots then break end
            keepEggs[i.id] = true
        end
    end
    local live = F.placedIds()
    local eggsOn, catsOn = on("s_eggs"), on("s_cats")
    for _, i in ipairs(M.items()) do
        if i.sellable and (not i.placed or i.placed == "") and not live[i.id] and not F.PAID[i.rarity] and not keepEggs[i.id] and not (S.soldIds and S.soldIds[i.id]) then
            local mut = i.mutation and i.mutation ~= "" and picked("s_keepm", i.mutation)
            local want = (i.kind == "Egg" and eggsOn and picked("s_rar", i.rarity)) or (i.kind == "Catboy" and catsOn and picked("s_crar", i.rarity))
            if want and not mut then
                out[#out + 1] = i.id
                value += tonumber(i.sellValue) or 0
                if #out >= 20 then break end
            end
        end
    end
    return out, value
end
function U.sell()
    if os.clock() - (S.sellAt or 0) < 1 then return end
    local ids, value = U.sellList()
    if #ids == 0 then return end
    S.sellAt = os.clock()
    S.soldFlag = nil
    M.fire("RequestSell", { itemIds = ids })
    local t0 = os.clock()
    while os.clock() - t0 < 1.5 and not S.soldFlag do task.wait(0.05) end
    if S.soldFlag then
        S.sold += #ids
        S.soldValue += value
        S.soldIds = S.soldIds or {}
        for _, id in ipairs(ids) do S.soldIds[id] = true end
    else
        S.sellAt = os.clock() + 6
        LOG("sell no pay", #ids, S.gmsg)
    end
end
function U.ownedTrails()
    local out = {}
    local t = S.snap and S.snap.trailsOwned
    if type(t) == "table" then
        for k, v in pairs(t) do
            if type(v) == "string" then out[v] = true elseif v then out[k] = true end
        end
    end
    return out
end
function U.candidates()
    local list = {}
    if on("u_pen") and D.Plot then
        local nx = D.Plot.Pen.Levels[M.num("PenLevel") + 2]
        if nx and type(nx.Cost) == "number" then list[#list + 1] = { id = "pen", cost = nx.Cost, go = function() M.fire("RequestShop", { action = "UpgradePen" }) end, done = function(a) return M.num("PenLevel") ~= a end, mark = M.num("PenLevel") } end
    end
    if on("u_wheel") and D.Speed then
        local nx = D.Speed.Treadmills[M.num("TreadmillTier") + 1]
        if nx and M.num("PenLevel") >= 1 then list[#list + 1] = { id = "wheel", cost = nx.Cost, go = function() M.fire("RequestShop", { action = "BuyTreadmill" }) end, done = function(a) return M.num("TreadmillTier") ~= a end, mark = M.num("TreadmillTier") } end
    end
    if on("u_bag") and D.Upg then
        local nx = D.Upg.Bag.Levels[M.num("BagLevel") + 2]
        if nx then list[#list + 1] = { id = "bag", cost = nx.Cost, go = function() M.fire("RequestUpgrade", { kind = "Bag" }) end, done = function(a) return M.num("BagLevel") ~= a end, mark = M.num("BagLevel") } end
    end
    if on("u_incub") and D.Upg then
        local nx = D.Upg.Eggs.Levels[M.num("EggsLevel") + 2]
        if nx then list[#list + 1] = { id = "incub", cost = nx.Cost, go = function() M.fire("RequestUpgrade", { kind = "Eggs" }) end, done = function(a) return M.num("EggsLevel") ~= a end, mark = M.num("EggsLevel") } end
    end
    if on("u_trail") and D.Speed and S.snap then
        local owned = U.ownedTrails()
        for _, t in ipairs(D.Speed.Trails) do
            if not owned[t.Key] and type(t.Cost) == "number" then
                local key = t.Key
                list[#list + 1] = { id = "trail", cost = t.Cost, go = function() M.fire("RequestShop", { action = "BuyTrail", key = key }) end, done = function() return U.ownedTrails()[key] == true end, mark = 0 }
                break
            end
        end
    end
    table.sort(list, function(a, b) return a.cost < b.cost end)
    return list
end
function U.buyOne()
    S.buyCool = S.buyCool or {}
    local money, keep = M.num("Money"), U.keep()
    for _, c in ipairs(U.candidates()) do
        if (S.buyCool[c.id] or 0) < os.clock() and money - c.cost >= keep then
            c.go()
            local t0 = os.clock()
            while os.clock() - t0 < 1.5 and not c.done(c.mark) do task.wait(0.05) end
            if c.done(c.mark) then
                S.bought += 1
                LOG("bought", c.id, c.cost)
            else
                S.buyCool[c.id] = os.clock() + 20
                LOG("buy refused", c.id, S.gmsg)
            end
            return true
        end
    end
    return false
end
function U.equipTrail()
    if not on("u_trail") or not D.Speed or not S.snap then return end
    if os.clock() - (S.trailAt or 0) < 3 then return end
    local owned, best = U.ownedTrails(), nil
    for _, t in ipairs(D.Speed.Trails) do
        if owned[t.Key] and (not best or t.Mult > best.Mult) then best = t end
    end
    if best and M.attr("TrailEquipped") ~= best.Key then
        S.trailAt = os.clock()
        M.fire("RequestShop", { action = "EquipTrail", key = best.Key })
    end
end
function U.claims()
    if on("r_index") and S.snap and type(S.snap.index) == "table" and os.clock() - (S.indexAt or 0) > 5 then
        for _, v in pairs(S.snap.index) do
