function P.spotFor(name)
    if name == "Lobby" then return F.lobby() end
    if name == "Bank Line" then return F.home() end
    local b = M.base()
    if name == "Base" and b then
        local fr = F.frame(b)
        return fr and F.near(fr.Position)
    end
    if name == "Cat Wheel" and b and b:FindFirstChild("Treadmill") then
        local t = b.Treadmill.Position
        return F.stand(t.X, t.Z, t.Y)
    end
    for _, z in ipairs(F.ZONES) do
        if F.zoneLabel(z) == name then
            local rt = Workspace:FindFirstChild("Runtime")
            local eggs = rt and rt:FindFirstChild("WorldEggs")
            for _, e in ipairs(eggs and eggs:GetChildren() or {}) do
                if e:GetAttribute("ZoneIndex") == z.i then return F.near(e:GetPivot().Position) end
            end
            local last = S.zonePos and S.zonePos[z.i]
            return last and F.near(last)
        end
    end
end
function P.tp(name)
    local s = P.spotFor(name)
    if s then
        S.holdUntil = os.clock() + 10
        M.go(s)
    else
        notify(__T["Not available right now"])
    end
end
